-- Australia Early Childhood Teacher profile.
update ingest.occupations_au
set shortage_rating = 5, on_csol = true, median_salary_aud = null,
    confidence = 'official-profile-osl-csol',
    source_name = 'ABS OSCA 2024 v1.0 + JSA 2025 OSL + current skilled occupation instrument',
    source_url = 'https://www.abs.gov.au/statistics/classifications/osca-occupation-standard-classification-australia/2024-version-1-0/browse-classification/2/25/251/2511/251131',
    last_verified = '2026-08-09', anzsco_v13 = '241111'
where anzsco_code = '251131' and occupation_en = 'Early Childhood (Pre-primary School) Teacher';

update ingest.visa_occupation_status_au
set reviewed_at = now(), reviewer_note = 'Reviewed current OSCA 251131 correspondence to ANZSCO 241111. Current skilled occupation instrument lists Early Childhood (Pre-primary School) Teacher 241111 with ACECQA as assessing authority.'
where osca_code = '251131' and anzsco_v13_code = '241111' and list_name = 'Core Skills Occupation List (CSOL)' and status = 'eligible';

update public.courses_au set official_course_url='https://www.deakin.edu.au/course/bachelor-early-childhood-education-international', official_url_status='verified', official_url_checked_at=now(), official_url_source='Provider international course page, verified 2026-08-09' where institution_id='deakin-university' and course_code='102806B';
update public.courses_au set official_course_url='https://www.deakin.edu.au/course/master-teaching-early-childhood-international', official_url_status='verified', official_url_checked_at=now(), official_url_source='Provider international course page, verified 2026-08-09' where institution_id='deakin-university' and course_code='114296J';

insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at)
