insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at)
values ('AU:early-childhood-teacher','2026-05-01',null,null,null,null,1852,null,null,null,null,1072.66667,'2026-05-01',-21.87,5.72,12.08,20,0,5,0,13,0,5,10,2,55,'career-opportunity-v1','provisional',jsonb_build_object('current_classification_scope','Current OSCA 251131 Early Childhood (Pre-primary School) Teacher is a Skill Level 1 occupation. Early Childhood Educators and Room Leaders, preschool directors and Special Education Teachers are explicitly excluded.','legacy_mapping','Current migration occupation is ANZSCO 241111 Early Childhood (Pre-primary School) Teacher. JSA labour-market series currently available in CampCareer are broader ANZSCO 2411 observations rather than a reviewed six-digit 241111 profile.','broader_anzsco_2411_context',jsonb_build_object('employment_total',71900,'median_weekly_earnings_aud',1906,'median_hourly_earnings_aud',50,'part_time_share_pct',43,'female_share_pct',95,'median_age',37,'average_full_time_hours',41,'data_as_at','2026-02-01','scope','ANZSCO 2411 Early Childhood (Pre-primary School) Teachers unit-group context'),'earnings_scope','No reviewed six-digit earnings observation is used for the current OSCA occupation. Broader 2411 earnings are context only, so the salary component is zero.','vacancy_scope','May 2026 IVI three-month-average vacancies are 1,072.66667 at broader ANZSCO 2411, down from 1,373 in May 2025, about -21.87% year on year. Vacancy intensity and trend are not credited as exact occupation observations.','projection_scope','JSA broader ANZSCO 2411 projections are +5.72% from May 2025 to May 2030 and +12.08% to May 2035, receiving partial growth credit.','shortage_note','The reviewed JSA 2025 Occupation Shortage List records current OSCA 251131 as a national shortage occupation. Regional shortage is left null in this profile rather than inferred from the national result.','visa_basis','The current skilled occupation instrument lists ANZSCO 241111 Early Childhood (Pre-primary School) Teacher with ACECQA as assessing authority. Occupation-list inclusion and a positive skills assessment do not guarantee an individual visa outcome.','registration_basis','OSCA states registration or licensing is required. Early childhood teacher registration/accreditation requirements vary by state, territory and employment setting; applicants must confirm the relevant jurisdictional rules.','entry_level_basis','Deakin Bachelor of Early Childhood Education 102806B is an AQF Level 7 ACECQA-approved initial teacher education route. Deakin Master of Teaching (Early Childhood) 114296J is an AQF Level 9 graduate-entry ACECQA-approved route.','score_note','Full shortage and migration credit are supported by exact occupation evidence. Broader labour-market observations are not scored as exact employment, earnings or vacancy intensity; broader long-run growth receives partial credit.'),'2026-08-09')
